// Validate Step 1: Motivation Layer output
const input = $input.first().json;

let motivation;
try {
  const content = input.message?.content || input;
  motivation = typeof content === 'string' ? JSON.parse(content) : content;
} catch (e) {
  throw new Error('Failed to parse Motivation Layer JSON: ' + e.message);
}

const required = ['stakeholders', 'drivers', 'goals', 'outcomes'];
for (const key of required) {
  if (!Array.isArray(motivation[key])) {
    motivation[key] = [];
  }
}

const validateIds = (arr, prefix) => {
  return arr.map(el => {
    if (!el.id || !el.id.startsWith(prefix)) {
      el.id = prefix + (el.name || 'item').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '').slice(0, 30);
    }
    if (!el.type) el.type = prefix.replace('id-', '').replace(/-/g, '');
    return el;
  });
};

motivation.stakeholders = validateIds(motivation.stakeholders, 'id-sh-');
motivation.drivers = validateIds(motivation.drivers, 'id-dr-');
motivation.goals = validateIds(motivation.goals, 'id-gl-');
motivation.outcomes = validateIds(motivation.outcomes, 'id-oc-');

return [{ json: { motivation } }];

