// Validate Step 3: Business Layer output
const input = $input.first().json;

let businessArch;
try {
  const content = input.message?.content || input;
  businessArch = typeof content === 'string' ? JSON.parse(content) : content;
} catch (e) {
  throw new Error('Failed to parse Business Layer JSON: ' + e.message);
}

const required = ['actors', 'processes', 'services', 'objects'];
for (const key of required) {
  if (!Array.isArray(businessArch[key])) {
    businessArch[key] = [];
  }
}

// Initialize useCases if not present
if (!Array.isArray(businessArch.useCases)) {
  businessArch.useCases = [];
}

const validateIds = (arr, prefix) => {
  return arr.map(el => {
    if (!el.id || !el.id.startsWith(prefix)) {
      el.id = prefix + (el.name || 'item').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '').slice(0, 30);
    }
    return el;
  });
};

businessArch.actors = validateIds(businessArch.actors, 'id-ba-');
businessArch.processes = validateIds(businessArch.processes, 'id-bp-');
businessArch.services = validateIds(businessArch.services, 'id-bs-');
businessArch.objects = validateIds(businessArch.objects, 'id-bo-');

// Validate use cases
businessArch.useCases = businessArch.useCases.map(uc => {
  // Generate ID if missing
  if (!uc.id || !uc.id.startsWith('id-uc-')) {
    uc.id = 'id-uc-' + (uc.name || 'use-case').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '').slice(0, 30);
  }
  // Ensure type is set
  if (!uc.type) uc.type = 'BusinessInteraction';
  // Ensure steps is an array
  if (!Array.isArray(uc.steps)) uc.steps = [];
  // Ensure required fields exist
  if (!uc.trigger) uc.trigger = '';
  if (!uc.outcome) uc.outcome = '';
  if (!uc.actor) uc.actor = businessArch.actors[0]?.id || '';
  return uc;
});

return [{ json: { businessArch } }];

