={{ {
  model: 'llama3.1:8b-instruct-q4_K_M',
  messages: [
    {
      role: 'system',
      content: 'You are a classifier for an Architecture pipeline. Analyze the user input and determine the mode, intent, and extract project information.\n\nMODE RULES:\n- mode=chat: For queries, help requests, status checks. Keywords: help, status, list, artifacts, jobs, what, how, show, get, query, ?\n- mode=execute: For creating/building/generating architecture. Keywords: build, create, generate, make, develop, design a, implement\n\nSPECIAL RULE: If the input is a LONG document (multiple paragraphs, sections, technical content), this is ALWAYS mode=execute because the user is providing requirements to process.\n\nIf input is a single word like "help", "list", "jobs", "status" - it is ALWAYS mode=chat.\nIf input asks a question or requests information - it is mode=chat.\nOnly short queries should be mode=chat. Long documents = mode=execute.\n\nPROJECT EXTRACTION (CRITICAL):\n- ALWAYS extract the projectSlug from the input text\n- Look for patterns like "project X", "for X", "X project", or project names in the text\n- The projectSlug should be a lowercase-hyphenated string (e.g., "healthcare-appointment-scheduler")\n- If no project name is found, set projectSlug to null\n\nChat intents: help, status, artifacts, jobs, list\nExecute intents: create, build, generate\n\nOutput JSON only.'
    },
    { role: 'user', content: ($json.suggestedMode === 'execute' ? 'EXECUTE MODE - Process these requirements: ' : '') + ($json.rawInput || $json.requirements) }
  ],
  stream: false,
  format: {
    type: 'object',
    required: ['mode', 'intent', 'projectSlug'],
    properties: {
      mode: { type: 'string', enum: ['chat', 'execute'] },
      intent: { type: 'string' },
      projectSlug: { type: 'string', description: 'The project name/slug extracted from the input text, lowercase with hyphens' },
      requirements: { type: 'string' }
    }
  },
  options: { temperature: 0.1 }
} }}

parameters.jsCode:
// Build Azure DevOps push payload
const ctx = $("Build Git Script").first().json;
const repoInfo = $("Get Azure Repo Info").first().json;
const branchCheck = $("Check Azure Branch").first().json;
const fileCheck = $json;
const projectSlug = ctx.projectSlug;
const jobId = ctx.jobId;

const artifactContent = ctx.artifactContent || ctx.artifactMarkdown || ctx.content || "";
const artifactPath = "/docs/artifact.md";
const branchName = `refs/heads/${projectSlug}`;

let oldObjectId = "0000000000000000000000000000000000000000";
let changeType = "add";

// Check if branch exists
if (branchCheck.value && branchCheck.value.length > 0) {
  oldObjectId = branchCheck.value[0].objectId;
}

// Check if file exists (statusCode 200 = exists, 404 = doesn't exist)
const fileExists = fileCheck.statusCode === 200;
if (fileExists) {
  changeType = "edit";
} else {
  changeType = "add";
}

const changes = [{
  changeType: changeType,
  item: { path: `/${projectSlug}-docs${artifactPath}` },
  newContent: {
    content: Buffer.from(artifactContent).toString("base64"),
    contentType: "base64encoded"
  }
}];

return [{
  json: {
    ...ctx,
    azurePushPayload: {
      refUpdates: [{ name: branchName, oldObjectId: oldObjectId }],
      commits: [{ comment: `Add artifacts for ${projectSlug} (job ${jobId})`, changes: changes }]
    },
    azureRepoInfo: repoInfo,
    branchExists: branchCheck.value && branchCheck.value.length > 0,
    fileExists: fileExists,
    changeType: changeType
  }
}];

// Normalize rows from Postgres
const items = $input.all();
if (!items.length) return [{ json: { rows: [] } }];
const rows = items.map(i => i.json);
return [{ json: { rows } }];

// Determine if we have an existing BRD from DB
const rows = Array.isArray($json.rows) ? $json.rows : [];
const first = rows[0] || null;
const brd = first && typeof first.content === 'object' ? first.content : null;
const hasBrd = !!(brd && brd.type === 'brd' && brd.title && brd.executiveSummary);

return hasBrd
  ? [{ json: { hasBrd: true, brdFromDb: brd } }]
  : [{ json: { hasBrd: false } }];

// Parse BRD from Ollama response
const response = $json;
let brd;

try {
  // Ollama returns response in message.content
  const content = response.message?.content;
  if (typeof content === 'string') {
    brd = JSON.parse(content);
  } else if (typeof content === 'object') {
    brd = content;
  } else {
    throw new Error('Unexpected BRD response format');
  }
} catch (e) {
  // Fallback: wrap requirements as simple BRD structure
  const requirements = $('Use Requirements').first().json.requirements;
  brd = {
    type: 'brd',
    title: 'Generated from Requirements',
    version: '1.0',
    executiveSummary: requirements.substring(0, 500),
    problemStatement: {
      currentState: 'Requirements provided directly',
      painPoints: ['Requirements need to be analyzed'],
      impact: 'Architecture generation from raw requirements'
    },
    businessObjectives: [{ objective: 'Implement requirements', priority: 'high' }],
    stakeholders: [],
    scope: { inScope: [requirements], outOfScope: [] },
    constraints: [],
    assumptions: [],
    successCriteria: []
  };
}

return [{ json: { brdSource: 'generated', brdFromGenerated: brd } }];

const projectItems = $input.all();
const firstItem = projectItems[0]?.json || {};
const hasProject = Object.keys(firstItem).length > 0 && firstItem.id;

if (hasProject) {
  return projectItems.map(item => ({
    json: {
      ...item.json,
      projectExists: true,
      projectData: item.json
    }
  }));
} else {
  const initParams = $('Initialize Parameters').first()?.json || {};
  return [{
    json: {
      projectExists: false,
      projectSlug: initParams.projectSlug || 'direct-requirements',
      requirements: initParams.requirements || '',
      jobId: 'direct-' + Date.now()
    }
  }];
}

// Prepare context for newly created project
const project = $json;
const initParams = $('Initialize Parameters').first().json;

return [{
  json: {
    id: project.id,
    slug: project.slug,
    name: project.name || initParams.projectName || project.slug,
    projectId: project.id,
    projectSlug: project.slug,
    projectName: project.name || initParams.projectName || project.slug,
    requirements: initParams.requirements,
    isNewProject: true
  }
}];

// Match document concepts to Healthcare Capability Reference Model via Qdrant
const step0Content = $('Step 0: Parse Document Structure').first().json.message?.content || '';
const motivation = $('Validate Motivation Layer').first().json.motivation || {};

// Extract key business concepts from the parsed document
const conceptsToMatch = [];

// Get processes and services mentioned
const processMatch = step0Content.match(/###\s*Processes[\s\S]*?(?=###|##|$)/i);
if (processMatch) {
  const lines = processMatch[0].split('\n').filter(l => l.trim().startsWith('-'));
  lines.forEach(l => conceptsToMatch.push(l.replace(/^-\s*/, '').trim()));
}

const serviceMatch = step0Content.match(/###\s*Services[\s\S]*?(?=###|##|$)/i);
if (serviceMatch) {
  const lines = serviceMatch[0].split('\n').filter(l => l.trim().startsWith('-'));
  lines.forEach(l => conceptsToMatch.push(l.replace(/^-\s*/, '').trim()));
}

// Add goals as capability hints
(motivation.goals || []).forEach(g => conceptsToMatch.push(g.name));

if (conceptsToMatch.length === 0) {
  return [{ json: { matchedCapabilities: [], conceptsSearched: 0, passThrough: $json } }];
}

const searchQuery = conceptsToMatch.slice(0, 10).join(' ');

let embedding = null;
try {
  const embeddingResponse = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://ollama:11434/api/embeddings',
    body: { model: 'nomic-embed-text', prompt: searchQuery },
    json: true
  });
  embedding = embeddingResponse.embedding;
} catch (e) {
  return [{ json: { matchedCapabilities: [], error: 'Embedding failed: ' + e.message, passThrough: $json } }];
}

let matchedCapabilities = [];
try {
  const qdrantResponse = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://qdrant:6333/collections/capability-maps/points/search',
    body: { vector: embedding, limit: 15, with_payload: true, score_threshold: 0.60 },
    json: true
  });

  const results = qdrantResponse.result || [];
  const seen = new Set();
  results.forEach(hit => {
    const payload = hit.payload || {};
    const meta = payload.metadata || {};
    const level = meta.level || payload.level;
    const capability = payload.capability || meta.l3 || meta.l2 || meta.l1;
    const path = payload.path || '';
    const definition = payload.definition || '';

    if (capability && !seen.has(capability)) {
      seen.add(capability);
      matchedCapabilities.push({
        id: payload.id || 'cap-' + capability.toLowerCase().replace(/\s+/g, '-'),
        level: level,
        capability: capability,
        path: path,
        definition: definition.substring(0, 200),
        score: hit.score
      });
    }
  });

  matchedCapabilities.sort((a, b) => {
    if (a.level !== b.level) return (a.level === 2 || a.level === 3) ? -1 : 1;
    return b.score - a.score;
  });
  matchedCapabilities = matchedCapabilities.slice(0, 10);
} catch (e) {
  matchedCapabilities = [];
}

return [{ json: { matchedCapabilities, conceptsSearched: conceptsToMatch.length, searchQuery: searchQuery.substring(0, 200), passThrough: $json } }];

parameters.jsonBody:
={{ {
  model: $('Initialize Parameters').first().json.ollamaModel,
  messages: [
    {
      role: 'system',
      content: 'You are a Technical Architect generating sequence diagrams from use cases.\n\nFor each use case, map business steps to technical component interactions.\n\nOUTPUT FORMAT (CRITICAL - follow exactly):\n\n1. participants: Array of ONLY component names (strings)\n   CORRECT: ["Web App", "API Service", "Database"]\n   WRONG: ["Web App: does something", "API Service: calls DB"]\n\n2. mainFlow: Array of step objects with THREE separate fields:\n   - from: Component name ONLY (e.g., "User")\n   - to: Component name ONLY (e.g., "Web App")\n   - action: Description of what happens (e.g., "Clicks login button")\n\n   CORRECT: {"from": "User", "to": "Web App", "action": "Submits eligibility request"}\n   WRONG: {"from": "User", "to": "Web App: Submits eligibility request", "action": ""}\n\n3. alternateFlows: Same format as mainFlow for error/alternate paths\n\nRULES:\n- Use actual component names from the application architecture\n- Keep from/to as plain component names without descriptions\n- Put ALL descriptions in the action field\n- Include return messages (responses back to caller)\n- Cover error scenarios in alternateFlows'
    },
    {
      role: 'user',
      content: '## Use Cases\\n' + JSON.stringify($('Validate Business Layer').first().json.businessArch.useCases || [ ], null, 2) + '\\n\\n## Application Components\\n' + JSON.stringify($('Validate Application Layer').first().json.applicationArch || { }, null, 2) + '\\n\\n## Actors\\n' + JSON.stringify($('Validate Business Layer').first().json.businessArch.actors || [ ], null, 2)
    }
  ],
  stream: false,
  format: {
    type: 'object',
    required: ['sequenceDiagrams'],
    properties: {
      sequenceDiagrams: {
        type: 'array',
        items: {
          type: 'object',
          required: ['useCaseId', 'useCaseName', 'trigger', 'actors', 'participants', 'mainFlow'],
          properties: {
            useCaseId: { type: 'string' },
            useCaseName: { type: 'string' },
            trigger: { type: 'string' },
            actors: { type: 'array', items: { type: 'string' } },
