// Validate Sequence Diagrams and generate Markdown output
const input = $input.first().json;
const appArch = $('Validate Application Layer').first().json.applicationArch || {};
const useCases = $('Validate Business Layer').first().json.businessArch?.useCases || [];
const actors = $('Validate Business Layer').first().json.businessArch?.actors || [];

let diagrams;
try {
  const content = input.message?.content || input;
  diagrams = typeof content === 'string' ? JSON.parse(content) : content;
} catch (e) {
  throw new Error('Failed to parse Sequence Diagrams JSON: ' + e.message);
}

if (!Array.isArray(diagrams.sequenceDiagrams)) {
  diagrams.sequenceDiagrams = [];
}

// Get all component names from application architecture
const allComponents = new Set();
['components', 'services', 'interfaces'].forEach(key => {
  (appArch[key] || []).forEach(c => allComponents.add(c.name));
});

// Add actors
actors.forEach(a => allComponents.add(a.name));

// Common actor aliases that are valid
const validAliases = ['User', 'Actor', 'System', 'External System'];

// Validate and enrich each diagram
const validatedDiagrams = diagrams.sequenceDiagrams.map(d => {
  const missingComponents = [];
  const participants = new Set(d.participants || []);

  const checkParticipant = (name) => {
    if (!name) return;
    if (allComponents.has(name) || validAliases.includes(name)) return;
    // Fuzzy match
    const match = Array.from(allComponents).find(c => 
      c.toLowerCase().includes(name.toLowerCase()) || 
      name.toLowerCase().includes(c.toLowerCase())
    );
    if (!match) missingComponents.push(name);
  };

  // Check main flow participants
  (d.mainFlow || []).forEach(step => {
    checkParticipant(step.from);
    checkParticipant(step.to);
    participants.add(step.from);
    participants.add(step.to);
  });

  // Check alternate flows participants
  (d.alternateFlows || []).forEach(alt => {
    (alt.steps || []).forEach(step => {
      checkParticipant(step.from);
      checkParticipant(step.to);
      participants.add(step.from);
      participants.add(step.to);
    });
  });

  return {
    ...d,
    participants: Array.from(participants),
    validation: {
      allComponentsMapped: missingComponents.length === 0,
      missingComponents: [...new Set(missingComponents)]
    }
  };
});

// Generate Markdown output
let markdown = '# Sequence Diagrams\n\n';
let allValid = true;

validatedDiagrams.forEach((d, idx) => {
  markdown += `## ${idx + 1}. ${d.useCaseName}\n\n`;
  markdown += `**Use Case ID:** \`${d.useCaseId}\`\n\n`;
  markdown += `**Trigger:** ${d.trigger || 'N/A'}\n\n`;
  markdown += `**Actors:** ${(d.actors || []).join(', ') || 'N/A'}\n\n`;
  markdown += `**Participants:** ${d.participants.join(', ')}\n\n`;

  markdown += `### Main Flow\n\n`;
  markdown += `| # | From | To | Action |\n`;
  markdown += `|---|------|-----|--------|\n`;
  (d.mainFlow || []).forEach((step, stepIdx) => {
    markdown += `| ${stepIdx + 1} | ${step.from} | ${step.to} | ${step.action} |\n`;
  });

  if (d.alternateFlows && d.alternateFlows.length > 0) {
    markdown += `\n### Alternate Flows\n\n`;
    d.alternateFlows.forEach((alt, altIdx) => {
      markdown += `#### ${altIdx + 1}. ${alt.condition}\n\n`;
      markdown += `| # | From | To | Action |\n`;
      markdown += `|---|------|-----|--------|\n`;
      (alt.steps || []).forEach((step, stepIdx) => {
        markdown += `| ${stepIdx + 1} | ${step.from} | ${step.to} | ${step.action} |\n`;
      });
      markdown += `\n`;
    });
  }

  markdown += `### Validation\n\n`;
  if (d.validation.allComponentsMapped) {
    markdown += `✅ All participants mapped to application components\n`;
  } else {
    allValid = false;
    markdown += `⚠️ Missing component mappings: ${d.validation.missingComponents.join(', ')}\n`;
  }
  markdown += `\n---\n\n`;
});

return [{
  json: {
    sequenceDiagrams: validatedDiagrams,
    markdown: markdown,
    diagramCount: validatedDiagrams.length,
    allValid: allValid
  }
}];

const init = $('Initialize Parameters').first().json;

// Try to get project from Load Project (existing) or Prepare Project Context (new)
let project = $('Load Project').first()?.json || {};
if (!project.id) {
  // For new projects, get from Prepare Project Context
  project = $('Prepare Project Context').first()?.json || {};
}

const job = $json;
return [{ json: { ...init, projectId: project.id || project.projectId, projectSlug: project.slug || project.projectSlug, projectName: project.name || project.projectName || project.slug, jobId: job.id } }];

// Collect BRD from either DB, existing BRD, or generated from requirements
const ctx = $('Pass Context').first().json;
const brdSource = $json.brdSource || 'db';

let brd;
if (brdSource === 'db') {
  // From database via Use Existing BRD
  const dbContent = $('Determine BRD Flow').first().json.brdFromDb;
  brd = dbContent || {};
} else if (brdSource === 'generated') {
  // From generated BRD via Format Generated BRD
  try {
    const msgContent = $json.message?.content;
    if (typeof msgContent === 'string') {
      brd = JSON.parse(msgContent);
    } else {
      brd = msgContent || {};
    }
  } catch (e) {
    brd = { type: 'brd', title: 'Generated BRD', executiveSummary: 'BRD generated from requirements' };
  }
} else {
  // Direct requirements (fallback)
  const requirements = $('Initialize Parameters').first().json.requirements || '';
  if (requirements.startsWith('{')) {
    try {
      brd = JSON.parse(requirements);
    } catch (e) {
      brd = { type: 'requirements', content: requirements };
    }
  } else {
    brd = { type: 'requirements', content: requirements };
  }
}

return [{ json: { ...ctx, brd, brdSource } }];

