businessArch.objects = validateIds(businessArch.objects, 'id-bo-');

// Validate use cases
businessArch.useCases = businessArch.useCases.map(uc => {
  // Generate ID if missing
  if (!uc.id || !uc.id.startsWith('id-uc-')) {
