  // Ensure type is set
  if (!uc.type) uc.type = 'BusinessInteraction';
  // Ensure steps is an array
  if (!Array.isArray(uc.steps)) uc.steps = [];
  // Ensure required fields exist
  if (!uc.trigger) uc.trigger = '';
  if (!uc.outcome) uc.outcome = '';
  if (!uc.actor) uc.actor = businessArch.actors[0]?.id || '';
  return uc;
});

return [{ json: { businessArch } }];

