const input = $input.first().json;

let applicationArch;
try {
  const content = input.message?.content || input;
  applicationArch = typeof content === 'string' ? JSON.parse(content) : content;
} catch (e) {
  throw new Error('Failed to parse Application Layer JSON: ' + e.message);
}

const required = ['components', 'services', 'interfaces', 'dataObjects', 'events'];
for (const key of required) {
  if (!Array.isArray(applicationArch[key])) {
    applicationArch[key] = [];
  }
}

const validateIds = (arr, prefix) => {
  return arr.map(el => {
    if (!el.id || !el.id.startsWith(prefix)) {
      const baseName = (el.name || 'item').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '').slice(0, 30);
      el.id = prefix + baseName;
    }
    return el;
  });
};

applicationArch.components = validateIds(applicationArch.components, 'id-ac-');
applicationArch.services = validateIds(applicationArch.services, 'id-as-');
applicationArch.interfaces = validateIds(applicationArch.interfaces, 'id-ai-');
applicationArch.dataObjects = validateIds(applicationArch.dataObjects, 'id-do-');
applicationArch.events = validateIds(applicationArch.events, 'id-ae-');

return [{ json: { applicationArch } }];

// Convert all architecture layers to ArchiMate 3.0 Exchange Format XML
// Implements Steps 5-8 of the doc-to-archimate formula

const ctx = $('Pass Context').first().json;
const motVal = $('Validate Motivation Layer').first().json;
const stratVal = $('Validate Strategy Layer').first().json;
const bizVal = $('Validate Business Layer').first().json;
const appVal = $('Validate Application Layer').first().json;

// Extract layer data
const motivation = motVal.motivation || {};
const strategy = stratVal.strategy || {};
const business = bizVal.businessArch || {};
const application = appVal.applicationArch || {};

// Utilities
const escXml = (s) => String(s || '').replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/'/g, '&apos;');
const fnv1a = (s) => { let h = 0x811c9dc5; for (let i = 0; i < (s||'').length; i++) { h ^= s.charCodeAt(i); h = (h * 0x01000193) >>> 0; } return ('0000000' + h.toString(16)).slice(-8); };

// ArchiMate type mapping
const typeMap = {
  'Stakeholder': 'Stakeholder', 'Driver': 'Driver', 'Goal': 'Goal', 'Outcome': 'Outcome',
  'CourseOfAction': 'CourseOfAction', 'Capability': 'Capability', 'Resource': 'Resource',
  'BusinessActor': 'BusinessActor', 'BusinessProcess': 'BusinessProcess',
  'BusinessService': 'BusinessService', 'BusinessObject': 'BusinessObject',
  'ApplicationComponent': 'ApplicationComponent', 'ApplicationService': 'ApplicationService',
  'ApplicationInterface': 'ApplicationInterface', 'DataObject': 'DataObject', 'ApplicationEvent': 'ApplicationEvent'
};

// Collect all elements
const elements = [];
const addElements = (arr, defaultType) => {
  for (const el of (arr || [])) {
    if (!el || !el.id) continue;
    const archType = typeMap[el.type] || defaultType;
    elements.push({ id: el.id, name: el.name || el.id, type: archType, layer: el.layer });
  }
};

// Add elements from each layer
addElements(motivation.stakeholders, 'Stakeholder');
addElements(motivation.drivers, 'Driver');
addElements(motivation.goals, 'Goal');
addElements(motivation.outcomes, 'Outcome');
addElements(strategy.coursesOfAction, 'CourseOfAction');
addElements(strategy.capabilities, 'Capability');
addElements(strategy.resources, 'Resource');
addElements(business.actors, 'BusinessActor');
addElements(business.processes, 'BusinessProcess');
addElements(business.services, 'BusinessService');
addElements(business.objects, 'BusinessObject');
addElements(application.components, 'ApplicationComponent');
addElements(application.services, 'ApplicationService');
addElements(application.interfaces, 'ApplicationInterface');
addElements(application.dataObjects, 'DataObject');
addElements(application.events, 'ApplicationEvent');

// STEP 5: Generate Relationships
const relationships = [];
let relCounter = 1;

// Stakeholder -> Driver (Association)
for (const sh of (motivation.stakeholders || [])) {
  for (const dr of (motivation.drivers || [])) {
    relationships.push({ id: `id-rel-${String(relCounter++).padStart(3, '0')}`, source: sh.id, target: dr.id, type: 'Association' });
  }
}

// Driver -> Goal (Influence)
for (const dr of (motivation.drivers || [])) {
  for (const gl of (motivation.goals || [])) {
    relationships.push({ id: `id-rel-${String(relCounter++).padStart(3, '0')}`, source: dr.id, target: gl.id, type: 'Influence' });
  }
}

// Outcome -> Goal (Realization)
for (const oc of (motivation.outcomes || [])) {
  for (const gl of (motivation.goals || [])) {
    relationships.push({ id: `id-rel-${String(relCounter++).padStart(3, '0')}`, source: oc.id, target: gl.id, type: 'Realization' });
  }
}

// CourseOfAction -> Outcome (Realization)
for (const coa of (strategy.coursesOfAction || [])) {
  for (const oc of (motivation.outcomes || []).slice(0, 2)) {
    relationships.push({ id: `id-rel-${String(relCounter++).padStart(3, '0')}`, source: coa.id, target: oc.id, type: 'Realization' });
  }
}

// Capability -> CourseOfAction (Realization)
for (const cap of (strategy.capabilities || [])) {
  for (const coa of (strategy.coursesOfAction || []).slice(0, 2)) {
    relationships.push({ id: `id-rel-${String(relCounter++).padStart(3, '0')}`, source: cap.id, target: coa.id, type: 'Realization' });
  }
}

// BusinessProcess -> Capability (Realization)
for (const bp of (business.processes || [])) {
  for (const cap of (strategy.capabilities || []).slice(0, 2)) {
    relationships.push({ id: `id-rel-${String(relCounter++).padStart(3, '0')}`, source: bp.id, target: cap.id, type: 'Realization' });
  }
}

// ApplicationService -> BusinessProcess (Serving)
for (const as of (application.services || [])) {
  for (const bp of (business.processes || []).slice(0, 2)) {
    relationships.push({ id: `id-rel-${String(relCounter++).padStart(3, '0')}`, source: as.id, target: bp.id, type: 'Serving' });
  }
}

// STEP 6: Generate Organizations
const genOrgItem = (label, refs) => {
  if (!refs || refs.length === 0) return '';
  const items = refs.map(r => `      <item><idRef>${escXml(r.id)}</idRef></item>`).join('\n');
  return `    <item>\n      <label xml:lang="en">${escXml(label)}</label>\n${items}\n    </item>`;
};

let orgXml = '  <organizations>\n';
orgXml += genOrgItem('Motivation', [...(motivation.stakeholders||[]), ...(motivation.drivers||[]), ...(motivation.goals||[]), ...(motivation.outcomes||[])]);
orgXml += '\n';
orgXml += genOrgItem('Strategy', [...(strategy.coursesOfAction||[]), ...(strategy.capabilities||[]), ...(strategy.resources||[])]);
orgXml += '\n';
orgXml += genOrgItem('Business', [...(business.actors||[]), ...(business.processes||[]), ...(business.services||[]), ...(business.objects||[])]);
orgXml += '\n';
orgXml += genOrgItem('Application', [...(application.components||[]), ...(application.services||[]), ...(application.interfaces||[]), ...(application.dataObjects||[]), ...(application.events||[])]);
orgXml += '\n';
orgXml += genOrgItem('Relations', relationships);
orgXml += '\n  </organizations>';

// STEP 7: Generate Views
let appViewNodes = '';
let y = 50;
const nodeWidth = 180, nodeHeight = 60, gap = 30;
let x = 50;

for (const comp of (application.components || [])) {
  const isExternal = comp.id.includes('-ext-');
  const [r, g, b] = isExternal ? [213, 213, 213] : [181, 211, 231];
  appViewNodes += `      <node xsi:type="Element" identifier="view-node-${fnv1a(comp.id)}" elementRef="${escXml(comp.id)}" x="${x}" y="${y}" w="${nodeWidth}" h="${nodeHeight}">\n        <style><fillColor r="${r}" g="${g}" b="${b}"/></style>\n      </node>\n`;
  x += nodeWidth + gap;
  if (x > 800) { x = 50; y += nodeHeight + gap; }
}

let viewsXml = `  <views>\n    <diagrams>\n      <view identifier="id-view-application" xsi:type="Diagram">\n        <name xml:lang="en">Application Architecture</name>\n${appViewNodes}      </view>\n    </diagrams>\n  </views>`;

// STEP 8: Assemble Final XML
let elementsXml = '  <elements>\n';
for (const el of elements) {
  elementsXml += `    <element identifier="${escXml(el.id)}" xsi:type="${escXml(el.type)}">\n      <name xml:lang="en">${escXml(el.name)}</name>\n    </element>\n`;
}
elementsXml += '  </elements>';

let relationshipsXml = '  <relationships>\n';
for (const rel of relationships) {
  relationshipsXml += `    <relationship identifier="${escXml(rel.id)}" source="${escXml(rel.source)}" target="${escXml(rel.target)}" xsi:type="${escXml(rel.type)}"/>\n`;
}
relationshipsXml += '  </relationships>';

const modelId = 'id-' + fnv1a(ctx.projectName + '-model');
const fullXml = `<?xml version="1.0" encoding="UTF-8"?>
<model xmlns="http://www.opengroup.org/xsd/archimate/3.0/"
       xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"
       xsi:schemaLocation="http://www.opengroup.org/xsd/archimate/3.0/ http://www.opengroup.org/xsd/archimate/3.1/archimate3_Diagram.xsd"
       identifier="${modelId}">
  <name xml:lang="en">${escXml(ctx.projectName)}</name>
  <documentation xml:lang="en">ArchiMate model generated using doc-to-archimate formula</documentation>
${elementsXml}
${relationshipsXml}
${orgXml}
${viewsXml}
</model>`;

return [{
  json: {
    ...ctx,
    fullXml,
    fullXmlHash: fnv1a(fullXml),
    elementCount: elements.length,
    relationshipCount: relationships.length
  }
}];

const ctx = $('Pass Context').first().json;
const archDir = ctx.projectSlug + '-docs/architecture';
return [{ json: { success: true, jobId: ctx.jobId, projectSlug: ctx.projectSlug, stage: 'architecture', archPaths: { business: archDir + '/business.archimate', application: archDir + '/application.archimate', data: archDir + '/data.archimate', technology: archDir + '/technology.archimate', full: archDir + '/full.archimate', orgFull: 'org-architecture/full.archimate' } } }];

// Architecture Pipeline Chat Handler
const input = $input.all()[0].json;
const intent = input.intent || 'help';
const projectSlug = input.projectSlug || null;
const query = input.query || input.rawInput || '';

const STAGE = 'architecture';
const ARTIFACT_TYPES = "'business_arch', 'application_arch', 'data_arch', 'infrastructure_arch', 'archimate_xml_full'";

let response = {
  agent: 'Enterprise Architect',
  stage: STAGE,
  intent: intent,
  success: true
};

switch (intent) {
  case 'help':
    response.content = `# Architecture Pipeline\n\n## Available Commands\n\n| Command | Description |\n|---------|-------------|\n| help | Show this help message |\n| status [project] | Check job status for a project |\n| artifacts [project] | List architecture artifacts for a project |\n| jobs | List recent jobs for this pipeline |\n| list | List all projects |\n\n## Architecture Domains Generated\n- Business Architecture (capabilities, actors, processes, services)\n- Application Architecture (components, interfaces, data objects)\n- Data Architecture (entities, flows, databases)\n- Infrastructure Architecture (nodes, networks, deployments)\n- ArchiMate XML Models\n\n## Execute Mode\n\nTo generate architecture, provide a project slug:\n\`\`\`\nGenerate architecture for my-project\n\`\`\`\n\nNote: Requires an existing BRD from the Business Analysis pipeline.`;
    response.message = 'Architecture Pipeline Help';
    break;

  case 'status':
    response.action = 'query_db';
    response.queryType = 'status';
    response.sql = projectSlug 
      ? `SELECT j.id, j.stage, j.status, j.created_at, j.completed_at, p.slug, p.name FROM architecture.jobs j JOIN architecture.projects p ON j.project_id = p.id WHERE j.stage = '${STAGE}' AND p.slug = '${projectSlug}' ORDER BY j.created_at DESC LIMIT 5`
      : `SELECT j.id, j.stage, j.status, j.created_at, j.completed_at, p.slug, p.name FROM architecture.jobs j JOIN architecture.projects p ON j.project_id = p.id WHERE j.stage = '${STAGE}' ORDER BY j.created_at DESC LIMIT 10`;
    break;

  case 'artifacts':
    response.action = 'query_db';
    response.queryType = 'artifacts';
    response.sql = projectSlug
      ? `SELECT a.id, a.type, a.version, a.created_at, p.slug, p.name FROM architecture.artifacts a JOIN architecture.projects p ON a.project_id = p.id WHERE a.type IN (${ARTIFACT_TYPES}) AND p.slug = '${projectSlug}' ORDER BY a.created_at DESC LIMIT 20`
      : `SELECT a.id, a.type, a.version, a.created_at, p.slug, p.name FROM architecture.artifacts a JOIN architecture.projects p ON a.project_id = p.id WHERE a.type IN (${ARTIFACT_TYPES}) ORDER BY a.created_at DESC LIMIT 20`;
    break;

  case 'jobs':
    response.action = 'query_db';
    response.queryType = 'jobs';
    response.sql = `SELECT j.id, j.stage, j.status, j.created_at, j.completed_at, p.slug, p.name FROM architecture.jobs j JOIN architecture.projects p ON j.project_id = p.id WHERE j.stage = '${STAGE}' ORDER BY j.created_at DESC LIMIT 20`;
    break;

  case 'list':
    response.action = 'query_db';
    response.queryType = 'projects';
    response.sql = `SELECT p.id, p.slug, p.name, p.created_at, p.updated_at, (SELECT COUNT(*) FROM architecture.artifacts a WHERE a.project_id = p.id AND a.type IN (${ARTIFACT_TYPES})) as arch_count, (SELECT COUNT(*) FROM architecture.jobs j WHERE j.project_id = p.id AND j.stage = '${STAGE}') as job_count FROM architecture.projects p ORDER BY p.updated_at DESC LIMIT 20`;
    break;

  default:
    response.success = false;
    response.message = `Unknown intent: ${intent}`;
    response.content = 'Try "help" to see available commands.';
}

return [{ json: response }];

// Parse and normalize incoming request
// Detect Open WebUI system prompts (auto-tagging, follow-ups, title generation)
const input = $json.body || $json;

// Check multiple possible field names for user input
// Open WebUI may send as chatInput, projectSlug, message, or query
// FIXED: Added projectSlug fallback for n8n_pipe.py compatibility
const chatInput = input.chatInput || input.message || input.query || input.projectSlug || '';
const requirements = input.requirements || '';

// Detect Open WebUI system prompts
const isAutoTag = chatInput.includes('### Task:') && chatInput.includes('Generate 1-3 broad tags');
const isFollowUp = chatInput.includes('### Task:') && chatInput.includes('Suggest 3-5 relevant follow-up');
const isTitleGen = chatInput.includes('### Task:') && chatInput.includes('Generate a concise');
// NEW: Detect search query generation prompts
const isSearchQuery = chatInput.includes('### Task:') && chatInput.includes('generating search queries');
const isSystemPrompt = isAutoTag || isFollowUp || isTitleGen || isSearchQuery;

// Also check requirements field for system prompts
const reqIsAutoTag = requirements.includes('### Task:') && requirements.includes('Generate 1-3 broad tags');
const reqIsFollowUp = requirements.includes('### Task:') && requirements.includes('Suggest 3-5 relevant follow-up');
const reqIsTitleGen = requirements.includes('### Task:') && requirements.includes('Generate a concise');
const reqIsSearchQuery = requirements.includes('### Task:') && requirements.includes('generating search queries');
const reqIsSystemPrompt = reqIsAutoTag || reqIsFollowUp || reqIsTitleGen || reqIsSearchQuery;

// Determine system prompt type
let systemPromptType = null;
if (isAutoTag || reqIsAutoTag) systemPromptType = 'auto-tag';
else if (isFollowUp || reqIsFollowUp) systemPromptType = 'follow-up';
else if (isTitleGen || reqIsTitleGen) systemPromptType = 'title-gen';
else if (isSearchQuery || reqIsSearchQuery) systemPromptType = 'search-query';

// Extract project slug - only use if it looks like a slug (short, no spaces)
const inputProjectSlug = input.projectSlug || null;
const looksLikeSlug = inputProjectSlug && inputProjectSlug.length < 100 && !inputProjectSlug.includes(' ');
const actualProjectSlug = looksLikeSlug ? inputProjectSlug : null;

// FIXED: Prioritize requirements field for rawInput when present
// Requirements field contains the actual generation request
let rawInput = '';
if (!(isSystemPrompt || reqIsSystemPrompt)) {
  // Use requirements if it looks like actual requirements text (longer than slug)
  if (requirements && requirements.length > 20) {
    rawInput = requirements;
  } else if (chatInput && chatInput.length > 0) {
    rawInput = chatInput;
  } else if (requirements) {
    rawInput = requirements;
  }
}

// NEW: Detect if this is an execute request based on input structure
// If requirements field has substantial content (>100 chars), assume execute mode
const hasSubstantialRequirements = requirements && requirements.length > 100;
const explicitMode = input.mode || null;
const suggestedMode = explicitMode || (hasSubstantialRequirements ? 'execute' : null);

return [{ json: {
  rawInput: rawInput,
  projectSlug: actualProjectSlug,
  projectName: input.projectName || null,
  requirements: input.requirements || null,
  sessionId: input.sessionId || null,
  isSystemPrompt: isSystemPrompt || reqIsSystemPrompt,
  systemPromptType: systemPromptType,
  suggestedMode: suggestedMode
} }];

// Handle Open WebUI system prompts (auto-tag, follow-up, title-gen)
const input = $json;
const promptType = input.systemPromptType;

let response = {};

switch (promptType) {
  case 'auto-tag':
    response = { tags: ['Architecture', 'Enterprise', 'ArchiMate'] };
    break;
  case 'follow-up':
    response = { follow_ups: [
      'What is the current project status?',
      'Can you show me the architecture artifacts?',
      'What are the recent architecture jobs?'
    ] };
    break;
  case 'title-gen':
    response = { title: 'Architecture Session' };
    break;
  default:
    response = { message: 'Unknown system prompt type' };
}

return [{ json: response }];

// Process LLM classification response
const parseInput = $('Parse Input').first().json;
const llmResponse = $json.message?.content || '{}';

let classified;
try {
  classified = typeof llmResponse === 'string' ? JSON.parse(llmResponse) : llmResponse;
} catch (e) {
  classified = { mode: 'chat', intent: 'help' };
}

const mode = classified.mode || 'chat';
const intent = classified.intent || 'help';

// Get project slug from parseInput, classified response, or generate fallback
let projectSlug = parseInput.projectSlug || classified.projectSlug || null;
const requirements = parseInput.requirements || classified.requirements || parseInput.rawInput;
let projectName = parseInput.projectName || classified.projectName || null;

// FIXED: Generate fallback slug if not provided
// Extract from project name, or generate from timestamp
if (!projectSlug && mode === 'execute') {
  if (projectName) {
    // Generate slug from project name
    projectSlug = projectName
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-|-$/g, '')
      .slice(0, 50);
  } else if (classified.projectSlug) {
    projectSlug = classified.projectSlug;
  } else {
    // Generate timestamp-based slug as last resort
    projectSlug = `project-${Date.now()}`;
  }
}

// Use slug as name if no name provided
if (!projectName && projectSlug) {
  projectName = projectSlug;
}

return [{ json: {
  mode,
  intent,
  projectSlug,
  projectName,
  requirements,
  rawInput: parseInput.rawInput,
  sessionId: parseInput.sessionId
} }];

// Format DB query results for chat response
const chatHandler = $('Chat Handler').first().json;
const queryType = chatHandler.queryType;
const rows = $input.all().map(i => i.json);

let content = '';
let message = '';

if (rows.length === 0) {
  content = 'No results found.';
  message = 'Empty result set';
} else {
  switch (queryType) {
    case 'projects':
      content = '# Projects\\n\\n| Slug | Name | Arch Artifacts | Jobs | Updated |\\n|------|------|----------------|------|---------|\\n';
      for (const row of rows) {
        const updated = row.updated_at ? new Date(row.updated_at).toLocaleDateString() : 'N/A';
        content += `| ${row.slug} | ${row.name || 'N/A'} | ${row.arch_count || 0} | ${row.job_count || 0} | ${updated} |\\n`;
      }
      message = `Found ${rows.length} project(s)`;
      break;

    case 'status':
    case 'jobs':
      content = '# Jobs\\n\\n| ID | Project | Stage | Status | Created | Completed |\\n|----|---------|-------|--------|---------|-----------|\\n';
      for (const row of rows) {
        const created = row.created_at ? new Date(row.created_at).toLocaleDateString() : 'N/A';
        const completed = row.completed_at ? new Date(row.completed_at).toLocaleDateString() : '-';
        const shortId = (row.id || '').substring(0, 8);
        content += `| ${shortId}... | ${row.slug || 'N/A'} | ${row.stage} | ${row.status} | ${created} | ${completed} |\\n`;
      }
      message = `Found ${rows.length} job(s)`;
      break;

    case 'artifacts':
      content = '# Artifacts\\n\\n| ID | Project | Type | Version | Created |\\n|----|---------|------|---------|---------|\\n';
      for (const row of rows) {
        const created = row.created_at ? new Date(row.created_at).toLocaleDateString() : 'N/A';
        const shortId = (row.id || '').substring(0, 8);
        content += `| ${shortId}... | ${row.slug || 'N/A'} | ${row.type} | v${row.version} | ${created} |\\n`;
      }
      message = `Found ${rows.length} artifact(s)`;
      break;

    default:
      content = '```json\\n' + JSON.stringify(rows, null, 2) + '\\n```';
      message = `Query returned ${rows.length} row(s)`;
  }
}

return [{ json: {
  agent: chatHandler.agent,
  stage: chatHandler.stage,
  intent: chatHandler.intent,
  success: true,
  content: content,
  message: message,
  rowCount: rows.length
} }];

